import{z as d,x as m,o as t,c as p,q as s,j as l,D as r,d as i,s as o,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"最小项与最大项","description":"","frontmatter":{"title":"最小项与最大项","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/minterm-maxterm.md","filePath":"cs/minterm-maxterm.md","lastUpdated":1791413859000}'),A={name:"cs/minterm-maxterm.md"};function B(u,a,f,_,h,x){const n=m("Mermaid");return t(),p("div",null,[a[2]||(a[2]=s('<h1 id="最小项与最大项" tabindex="-1">最小项与最大项 <a class="header-anchor" href="#最小项与最大项" aria-label="Permalink to &quot;最小项与最大项&quot;">​</a></h1><div class="epigraph"><p>任意布尔函数都可以写成「恰好那些使它为真的输入点」的或；对偶地，也可以写成最大项的与。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/de-morgan">德摩根与对偶</a>钉死了与、或、非可以等价变形。本课不重列交换律，也不从「什么是函数」另起。缺口是：公理保证能变形，还没有一张<strong>标准写法</strong>，把任一 \\(n\\) 元函数从真值表翻译成式子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个变量有 \\(2^n\\) 行真值表。公理课没有说怎样机械地写出一个实现它的式。缺口因此不是新运算，而是构造：每个输入赋值对应一个<strong>最小项</strong>（全部变量出现，为真的取原变量、为假的取反），函数等于那些使 \\(f=1\\) 的最小项之和。对偶：使 \\(f=0\\) 的赋值对应最大项，函数等于它们的积。</p><p><span class="marginnote">术语翻译：最小项就是「标准积项」——\\(n\\) 个变量一个不落地全出现，每个要么原样要么取反。它像只为真值表某一行定制的钥匙：输入与该行完全一致时输出 1，其余行全是 0；把所有钥匙用或门串起来，函数就造好了。</span></p><p>这是规范展开，通常不是最短。化简是<a href="/cs/karnaugh-map">卡诺图</a>的缺口。本课只钉「每个函数至少有这一份式子」，以便后课谈覆盖与无关项。</p><h3 id="最小项不是「一项里变量最少」" tabindex="-1">最小项不是「一项里变量最少」 <a class="header-anchor" href="#最小项不是「一项里变量最少」" aria-label="Permalink to &quot;最小项不是「一项里变量最少」&quot;">​</a></h3><p>名字里的「最小」指该项只在一个输入点为 1，不是字数最少。\\(abc\\) 与 \\(ab\\) 相比，前者才是三变量下的最小项。把「最短与项」当成最小项，后课卡诺圈会数错格子。</p><p><span class="marginnote">Harris 用 \\(\\sum m(1,2,5)\\) 记最小项之和，用 \\(\\prod M(\\cdot)\\) 记最大项之积。两种规范式表示同一函数，门的极性不同：与或相对或与。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对赋值 \\(a\\in\\{0,1\\}^n\\)，最小项 \\(m_a(x)=\\prod_i \\ell_i\\)，其中 \\(x_i=a_i\\) 时 \\(\\ell_i=x_i\\)，否则 \\(\\bar x_i\\)。则 \\(f(x)=\\sum_{a:f(a)=1}m_a(x)\\)。最大项 \\(M_a\\) 在 \\(a\\) 处为 0、别处为 1，\\(f(x)=\\prod_{a:f(a)=0}M_a(x)\\)。</p>',12)),(t(),l(E,null,{default:r(()=>[o(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TT%5B%22%E7%9C%9F%E5%80%BC%E8%A1%A8%22%5D%20--%3E%20SOP%5B%221%20%E7%9A%84%E8%A1%8C%20%E2%86%92%20%E6%9C%80%E5%B0%8F%E9%A1%B9%E4%B9%8B%E5%92%8C%22%5D%0A%20%20TT%20--%3E%20POS%5B%220%20%E7%9A%84%E8%A1%8C%20%E2%86%92%20%E6%9C%80%E5%A4%A7%E9%A1%B9%E4%B9%8B%E7%A7%AF%22%5D%0A%20%20SOP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8D%A1%E8%AF%BA%E5%9B%BE%E5%90%88%E5%B9%B6%22%5D%0A%20%20POS%20--%3E%20LATER%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"枚举是完备的，也是指数代价。后课组合块（MUX、译码器）会直接实现「按编号选一行」，本课先把「一行 = 一个最小项」说清。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为规范式就是好电路。\\(n=32\\) 时真值表有四十多亿行，逐行枚举毫无出路。规范式的价值在「每个函数至少有这一份式子」——它给化简和等价判据一个明确起点，而不是工程终点。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"规范式也让综合有起点：PLA 的与平面就是最小项（或乘积项）阵列。后课不完全指定函数会留下「既不是 1 也不是 0 的行」，那些行不进入本课的和、积——那是无关项，下一课才允许拿来化简。本课默认函数完全指定。",-1)),a[7]||(a[7]=e("p",null,"单个最小项如何「只认一行」，可以看两把钥匙过同一个或门：",-1)),(t(),l(E,null,{default:r(()=>[o(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%2001%22%5D%20--%3E%20M1%5B%22m1%20%3D%20%E9%9D%9Ex%C2%B7y%22%5D%0A%20%20IN%20--%3E%20M2%5B%22m2%20%3D%20x%C2%B7%E9%9D%9Ey%22%5D%0A%20%20M1%20--%3E%7C%22%E5%8C%B9%E9%85%8D%E8%A1%8C%EF%BC%8C%E5%87%BA%201%22%7C%20OR%5B%22%E6%88%96%E9%97%A8%22%5D%0A%20%20M2%20--%3E%7C%22%E4%B8%8D%E5%8C%B9%E9%85%8D%EF%BC%8C%E5%87%BA%200%22%7C%20OR%0A%20%20OR%20--%3E%20OUT%5B%22f%20%3D%201%EF%BC%9A01%20%E5%B1%9E%E4%BA%8E%201-%E9%9B%86%E5%90%88%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">数字实例：取 \\(f=\\sum m(1,2)\\)，即 1-集合为 \\(\\{01,10\\}\\)，规范式 \\(f=\\bar x y+x\\bar y\\)——这正是异或。按 0-集合 \\(\\{00,11\\}\\) 写最大项之积，得 \\(f=(x+y)(\\bar x+\\bar y)\\)。两条路画出同一个真值表，只是门的极性不同。</span></p><p>规范式也给等价性一个判据：化成最小项之和再比较集合。代价高，但定义清楚。代数化简必须保持这个集合不变。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画卡诺图，不引入质蕴涵项算法（Quine–McCluskey），不谈多输出函数的共享乘积项。时序电路的激励函数也会写成这种式，但状态还没有对象。</p><p>后课默认：任一组合功能都有 SOP/POS 规范式；化简是在保留 1-集合（或 0-集合）的前提下合并项。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最小项对应恰好一个输入点为 1；函数是其 1-集合的或。</li><li>最大项对偶；POS 与 SOP 表示同一完全指定函数。</li><li>「最小」不是「最短」；最短覆盖是后课。</li><li>出处：Harris and Harris, <em>Digital Design and Computer Architecture</em>。</li></ul>',7))])}const D=d(A,[["render",B]]);export{c as __pageData,D as default};
